<script>
$(function () {
    $('.select2-basic').select2({ width: '100%', minimumResultsForSearch: Infinity });
    $('.cuenta-select2').select2({width:'100%',language:{inputTooShort:function(){return 'Escriba al menos 2 caracteres';},searching:function(){return 'Buscando cuentas...';},noResults:function(){return 'No se encontraron cuentas';}},minimumInputLength:2,placeholder:function(){return $(this).data('placeholder');},allowClear:true,ajax:{url:'{{ route('amortizacion.cuentas') }}',dataType:'json',delay:300,data:function(params){return {term:params.term||''};},processResults:function(data){return data;},cache:true}});
    function activarLineas(){var activo=$('#usar_lineas').is(':checked');$('#lineas-container').toggle(activo);$('#lineas-lista input,#lineas-lista select').prop('disabled',!activo).prop('required',activo);if(activo)actualizarMonto();}
    function renumerar(){ $('#lineas-lista .linea-row').each(function(i){$(this).find('[name]').each(function(){$(this).attr('name',$(this).attr('name').replace(/lineas\[[0-9]+\]/,'lineas['+i+']'));});}); }
    function actualizarMonto(){var total=0;$('.linea-monto:enabled').each(function(){total+=parseFloat($(this).val())||0;});if($('#usar_lineas').is(':checked'))$('#monto-total').val(total.toFixed(2));}
    $('#usar_lineas').on('change',activarLineas);$(document).on('input','.linea-monto',actualizarMonto);
    $('#agregar-linea').on('click',function(){var i=$('#lineas-lista .linea-row').length;var row=$('#lineas-lista .linea-row:first').clone();row.find('input').each(function(){var n=$(this).attr('name')||'';$(this).attr('name',n.replace(/lineas\[[0-9]+\]/,'lineas['+i+']'));if(n.indexOf('plazo_meses')<0&&n.indexOf('numero_cuotas')<0&&n.indexOf('seguro_valor')<0)$(this).val('');});row.find('select').each(function(){$(this).attr('name',($(this).attr('name')||'').replace(/lineas\[[0-9]+\]/,'lineas['+i+']'));$(this).val($(this).find('option:first').val());});$('#lineas-lista').append(row);activarLineas();});
    $(document).on('click','.quitar-linea',function(){if($('#lineas-lista .linea-row').length>1)$(this).closest('.linea-row').remove();renumerar();actualizarMonto();});activarLineas();
});
</script>
